import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        Map<String, List<String>> kelas = new LinkedHashMap<String, List<String>>();

        String[][] data = {
            {"A", "Budi"},
            {"B", "Sari"},
            {"A", "Citra"}
        };

        for (String[] d : data) {
            if (!kelas.containsKey(d[0])) {
                kelas.put(d[0], new ArrayList<String>());
            }
            kelas.get(d[0]).add(d[1]);
        }

        System.out.println(kelas);

        for (Map.Entry<String, List<String>> e : kelas.entrySet()) {
            System.out.println("Kelas " + e.getKey() + ": " + e.getValue().size() + " siswa");
        }
    }
}

