import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class Main {
    public static void main(String[] args) {
        String[] kata = {"apel", "anggur", "beri", "ceri"};
        Map<String, List<String>> grup = new LinkedHashMap<String, List<String>>();
        for (String k : kata) {
            String huruf = k.substring(0, 1);
            if (!grup.containsKey(huruf)) {
                grup.put(huruf, new ArrayList<String>());
            }
            grup.get(huruf).add(k);
        }
        System.out.println(grup);
    }
}

